{
  "viz_type": "line",
  "encoding": {
    "x": {
      "field": "units",
      "type": "quantitative"
    },
    "y": {
      "field": "price",
      "type": "quantitative"
    },
    "color": {
      "field": "region",
      "type": "nominal"
    },
    "mark": {
      "type": "point"
    }
  },
  "transform": [
    {
      "calculate": "1",
      "as": "slope"
    },
    {
      "calculate": "datum.units * slope + datum.price - slope * min(datum.units)",
      "as": "trendline_y"
    }
  ],
  "encoding": {
    "y": {
      "field": "trendline_y",
      "type": "quantitative"
    }
  },
  "style": {
    "title": "Price against units with a fitted linear trend line"
  }
}

